function v3_report_e1(T,out)
angles=[5 7.5 10 12.5 15 17.5 20 22.5 25];durs=[2 4 6 8 10 12 16 20];minima=nan(9,2);pairs={};audit=true;
for i=1:9,for j=1:8,id=sprintf('V1_%04d_%04d',round(angles(i)*10),round(durs(j)*10));a=find(strcmp(T.id,[id '_A']));b=find(strcmp(T.id,[id '_B']));if isempty(a)||isempty(b),continue;end;ba=load(fullfile(out,'E1','cases',[id '_A'],'reference_bank.mat'));bb=load(fullfile(out,'E1','cases',[id '_B'],'reference_bank.mat'));same=true;for f={'time','x0','q_ref','omega_ref','tau_d'},same=same && max(abs(ba.(f{1})(:)-bb.(f{1})(:)))<1e-10;end;audit=audit && same;valid=T.complete(a) && T.complete(b) && ismember(string(T.status(a)),["SUCCESS","TRACKING_FAIL"]) && ismember(string(T.status(b)),["SUCCESS","TRACKING_FAIL"]);pairs{end+1}=struct('pair_id',id,'amplitude_deg',angles(i),'transition_s',durs(j),'status_A',string(T.status(a)),'status_B',string(T.status(b)),'comparable',valid,'same_reference',same,'rmse_A_deg',T.rmse_full_deg(a),'rmse_B_deg',T.rmse_full_deg(b));end;end
if ~isempty(pairs),P=struct2table([pairs{:}],'AsArray',true);writetable(P,fullfile(out,'tables','E1_paired.csv'));end
f=figure('Visible','off');tiledlayout(1,2);for cmg=[false true],Z=nan(9,8);for i=1:9,for j=1:8,k=find(T.amplitude_deg==angles(i) & T.transition_s==durs(j) & T.cmg==cmg,1);if isempty(k),continue;end;st=string(T.status(k));if st=="SUCCESS",Z(i,j)=5;minima(i,1+cmg)=min([minima(i,1+cmg),durs(j)],[],'omitnan');elseif st=="TRACKING_FAIL",Z(i,j)=4;elseif st=="CONTROLLER_FAIL",Z(i,j)=3;elseif st=="MODEL_DOMAIN_FAIL",Z(i,j)=2;else,Z(i,j)=1;end;end;end;nexttile;imagesc(Z,[1 5]);set(gca,'YDir','normal','XTick',1:8,'XTickLabel',durs,'YTick',1:9,'YTickLabel',angles);title(sprintf('CMG=%d',cmg));xlabel('Reference transition (s)');ylabel('Pitch increment (deg)');end;colormap([.5 .5 .5;.65 .45 .8;.9 .4 .2;1 .8 .2;.2 .65 .4]);cb=colorbar;cb.Ticks=1:5;cb.TickLabels={'infra','domain','controller','tracking','success'};v3_savefig(f,out,'E1_feasibility');
f=figure('Visible','off');plot(angles,minima(:,1),'-o',angles,minima(:,2),'-s');xlabel('Pitch increment (deg)');ylabel('Shortest tested successful transition (s)');legend('Surface MPC','CMG MPC');grid on;v3_savefig(f,out,'E1_min_duration');writetable(table(angles',minima(:,1),minima(:,2),'VariableNames',{'amplitude_deg','A_shortest_tested_s','B_shortest_tested_s'}),fullfile(out,'tables','E1_min_duration.csv'));
paper_json(fullfile(out,'reports','E1_acceptance.json'),struct('cases_total',height(T),'paired_cases',numel(pairs),'matrix_completed',height(T)==144,'comparability_pass',audit && numel(pairs)==72,'analysis_reproducible',false,'paper_E1_acceptance_complete',false,'note','Independent reanalysis must confirm stored metrics; domain points never count as physical inability'));
end
